theorem EnergyProfile.velocityEnergy_le_envelope
    {ν : ℝ} {a : RealSpatialL2}
    {u : ℝ → RealSpatialL2} {G : ℝ → Fin 3 → RealSpatialL2}
    (h : EnergyProfile ν a u G) {t : ℝ} (ht : 0 ≤ t) :
    velocityEnergy (u t) ≤
      QFA.Energy.envelope ‖a‖ ν (fun r => gradientEnergy (G r)) t

theorem EnergyProfile.exists_subcritical_good_time
    {ν δ : ℝ} {a : RealSpatialL2}
    {u : ℝ → RealSpatialL2} {G : ℝ → Fin 3 → RealSpatialL2}
    {Good : ℝ → Prop}
    (h : EnergyProfile ν a u G) (hν : 0 < ν)
    (hcut : ‖a‖ ^ 4 / (16 * Real.pi ^ 2 * ν ^ 5) < δ)
    (hgood : ∀ᵐ t ∂volume.restrict (Ioo (0 : ℝ) δ), Good t) :
    ∃ s, 0 < s ∧ s < δ ∧ Good s ∧
      velocityEnergy (u s) * gradientEnergy (G s) < 4 * Real.pi ^ 2 * ν ^ 4

theorem energyProfile_timeTranslate
    {ν s : ℝ} {a : RealSpatialL2}
    {u : ℝ → RealSpatialL2} {G : ℝ → Fin 3 → RealSpatialL2}
    (h : EnergyProfile ν a u G) (hs : 0 ≤ s)
    (hstart : EnergyStart ν u G s) :
    EnergyProfile ν (u s) (timeTranslate s u) (gradientTranslate s G)

theorem restricted_class_eq_singleton_of_eq_on_nonnegative
    {V : Type*} {C : Set (ℝ → V)} {v : ℝ → V}
    (hv : v ∈ C)
    (hEq : ∀ u ∈ C, ∀ t : ℝ, 0 ≤ t → u t = v t) :
    (fun u : ℝ → V => fun t : {t : ℝ // 0 ≤ t} => u t.1) '' C =
      {fun t : {t : ℝ // 0 ≤ t} => v t.1}

theorem restricted_class_eq_singleton_of_comparable
    {C : Set (ℝ → V)} {v : ℝ → V} {a₀ : V}
    (hv : v ∈ C)
    (hcomparisons : ∀ w ∈ C, ComparableOnNonnegative w v a₀) :
    (fun w : ℝ → V => fun t : {t : ℝ // 0 ≤ t} => w t.1) '' C =
      {fun t : {t : ℝ // 0 ≤ t} => v t.1}
